from datetime import datetime, timezone

from flask import request
from flask_jwt_extended import create_access_token, get_jwt_identity
from marshmallow import ValidationError
from werkzeug.security import generate_password_hash, check_password_hash

from app.models import db, User, Category, Task


def hash_password(password):
    return generate_password_hash(password)


def verify_password(password_hash, password):
    return check_password_hash(password_hash, password)


def generate_token(user_id):
    return create_access_token(identity=user_id)


def get_current_user():
    user_id = get_jwt_identity()
    return db.session.get(User, user_id)


def paginate_query(query, page, per_page, schema_class=None):
    paginated = query.paginate(page=page, per_page=per_page, error_out=False)
    data = []
    for item in paginated.items:
        d = item.to_dict()
        if schema_class:
            d = schema_class.dump(d)
        data.append(d)
    return {
        "data": data,
        "pagination": {
            "page": paginated.page,
            "per_page": paginated.per_page,
            "total": paginated.total,
            "pages": paginated.pages,
            "has_next": paginated.has_next,
            "has_prev": paginated.has_prev,
        },
    }


def apply_task_filters(query, status=None, priority=None, category_id=None,
                       assigned_to_id=None, search=None, sort_by=None, sort_order=None):
    if status:
        query = query.filter(Task.status == status)
    if priority:
        query = query.filter(Task.priority == priority)
    if category_id:
        query = query.filter(Task.category_id == category_id)
    if assigned_to_id:
        query = query.filter(Task.assigned_to_id == assigned_to_id)
    if search:
        pattern = f"%{search}%"
        query = query.filter(
            db.or_(Task.title.ilike(pattern), Task.description.ilike(pattern))
        )

    sort_column = getattr(Task, sort_by or "created_at", Task.created_at)
    if sort_order == "asc":
        query = query.order_by(sort_column.asc())
    else:
        query = query.order_by(sort_column.desc())

    return query


def parse_date(dt_value):
    if dt_value is None:
        return None
    if isinstance(dt_value, datetime):
        return dt_value
    if isinstance(dt_value, str):
        for fmt in (
            "%Y-%m-%dT%H:%M:%S.%fZ",
            "%Y-%m-%dT%H:%M:%SZ",
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d",
        ):
            try:
                naive = datetime.strptime(dt_value, fmt)
                return naive.replace(tzinfo=timezone.utc)
            except ValueError:
                continue
        raise ValidationError(f"Cannot parse date: {dt_value}")
    return dt_value

from flask import Blueprint, request, jsonify
from marshmallow import ValidationError

from app.models import db, User
from app.schemas import RegisterSchema, LoginSchema
from app.utils import hash_password, verify_password, generate_token

auth_bp = Blueprint("auth", __name__)


@auth_bp.route("/register", methods=["POST"])
def register():
    json_data = request.get_json(silent=True)
    if not json_data:
        return jsonify({"error": "Request body must be JSON."}), 400

    try:
        data = RegisterSchema().load(json_data)
    except ValidationError as err:
        return jsonify({"error": "Validation failed.", "details": err.messages}), 400

    if User.query.filter_by(username=data["username"]).first():
        return jsonify({"error": "Username already taken."}), 409

    if User.query.filter_by(email=data["email"]).first():
        return jsonify({"error": "Email already registered."}), 409

    user = User(
        username=data["username"],
        email=data["email"],
        password_hash=hash_password(data["password"]),
    )
    db.session.add(user)
    db.session.commit()

    token = generate_token(user.id)
    return jsonify({"message": "User registered.", "user": user.to_dict(), "token": token}), 201


@auth_bp.route("/login", methods=["POST"])
def login():
    json_data = request.get_json(silent=True)
    if not json_data:
        return jsonify({"error": "Request body must be JSON."}), 400

    try:
        data = LoginSchema().load(json_data)
    except ValidationError as err:
        return jsonify({"error": "Validation failed.", "details": err.messages}), 400

    user = User.query.filter_by(username=data["username"]).first()
    if not user or not verify_password(user.password_hash, data["password"]):
        return jsonify({"error": "Invalid username or password."}), 401

    token = generate_token(user.id)
    return jsonify({"message": "Login successful.", "user": user.to_dict(), "token": token}), 200

from flask import Blueprint, request, jsonify
from flask_jwt_extended import jwt_required
from marshmallow import ValidationError

from app.models import db, Task, Category, User
from app.schemas import TaskCreateSchema, TaskUpdateSchema, PaginationSchema
from app.utils import get_current_user, paginate_query, apply_task_filters, parse_date

task_bp = Blueprint("tasks", __name__)


@task_bp.route("", methods=["POST"])
@jwt_required()
def create_task():
    current_user = get_current_user()
    json_data = request.get_json(silent=True)
    if not json_data:
        return jsonify({"error": "Request body must be JSON."}), 400

    try:
        data = TaskCreateSchema().load(json_data)
    except ValidationError as err:
        return jsonify({"error": "Validation failed.", "details": err.messages}), 400

    if data.get("category_id"):
        cat = db.session.get(Category, data["category_id"])
        if not cat:
            return jsonify({"error": "Category not found."}), 404

    if data.get("assigned_to_id"):
        assignee = db.session.get(User, data["assigned_to_id"])
        if not assignee:
            return jsonify({"error": "Assigned user not found."}), 404

    task = Task(
        title=data["title"],
        description=data.get("description"),
        status=data.get("status", Task.STATUS_PENDING),
        priority=data.get("priority", Task.PRIORITY_MEDIUM),
        due_date=parse_date(data.get("due_date")),
        category_id=data.get("category_id"),
        created_by_id=current_user.id,
        assigned_to_id=data.get("assigned_to_id"),
    )
    db.session.add(task)
    db.session.commit()

    return jsonify(task.to_dict()), 201


@task_bp.route("", methods=["GET"])
@jwt_required()
def list_tasks():
    try:
        params = PaginationSchema().load(request.args)
    except ValidationError as err:
        return jsonify({"error": "Validation failed.", "details": err.messages}), 400

    query = Task.query
    query = apply_task_filters(
        query,
        status=params.get("status"),
        priority=params.get("priority"),
        category_id=params.get("category_id"),
        assigned_to_id=params.get("assigned_to_id"),
        search=params.get("search"),
        sort_by=params.get("sort_by"),
        sort_order=params.get("sort_order"),
    )

    result = paginate_query(query, page=params["page"], per_page=params["per_page"])
    return jsonify(result), 200


